import sys
from importlib.abc import MetaPathFinder
class Guard(MetaPathFinder):
    def find_spec(self, fullname, path=None, target=None):
        if fullname.split('.')[0] in {'app','services','fastapi','celery','psycopg','psycopg_pool','redis','httpx','sqlite3','torch'}:
            raise AssertionError('forbidden runtime import: ' + fullname)
sys.meta_path.insert(0, Guard())
def reject_services(event, arguments):
    if event in {'socket.connect','socket.bind','sqlite3.connect'}:
        raise AssertionError('forbidden initialization: ' + event)
sys.addaudithook(reject_services)
assert all('/Users/andy/tempo' not in path for path in sys.path)
import pytest
raise SystemExit(pytest.main(sys.argv[1:]))

